parameters.jsCode:
// Mengambil data dari node sebelumnya
const items = $input.all();

// Loop untuk mengubah file gambar menjadi teks acak-acakan (Base64)
for (let i = 0; i < items.length; i++) {
  // Kita ambil file dari kunci 'data'
  const fileBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  // Kita ubah jadi teks base64 dan simpan di kolom 'gambar_base64'
  items[i].json.gambar_base64 = fileBuffer.toString('base64');
}

return items;

// 1. Ambil Data dari LLM
let aiResponse;
if (!items || !items[0]) {
  return [{ json: { isValid: false, message: "Tidak ada data input dari AI." } }];
}

const inputData = items[0].json;
if (inputData.choices && inputData.choices[0]) {
  aiResponse = inputData.choices[0].message.content; 
} else if (inputData.text) {
  aiResponse = inputData.text; 
} else {
  aiResponse = inputData.content || "";
}

// 2. JURUS JSON HUNTER
let cleanJson = aiResponse;
const firstSquare = aiResponse.indexOf('[');
const lastSquare = aiResponse.lastIndexOf(']');
const firstCurly = aiResponse.indexOf('{');
const lastCurly = aiResponse.lastIndexOf('}');

if (firstSquare !== -1 && lastSquare !== -1) {
  cleanJson = aiResponse.substring(firstSquare, lastSquare + 1);
} else if (firstCurly !== -1 && lastCurly !== -1) {
  cleanJson = aiResponse.substring(firstCurly, lastCurly + 1);
}

try {
  const parsedRaw = JSON.parse(cleanJson);
  let transactionList = Array.isArray(parsedRaw) ? parsedRaw : [parsedRaw];

  // 3. KAMUS BULAN INDONESIA (Buat jaga-jaga kalau AI ngasih teks)
  const monthMap = {
    'januari': '01', 'jan': '01', 'februari': '02', 'feb': '02',
    'maret': '03', 'mar': '03', 'april': '04', 'apr': '04',
    'mei': '05', 'juni': '06', 'jun': '06', 'juli': '07', 'jul': '07',
    'agustus': '08', 'agu': '08', 'september': '09', 'sep': '09',
    'oktober': '10', 'okt': '10', 'november': '11', 'nov': '11',
    'desember': '12', 'des': '12'
  };

  // 4. LOOPING & SMART FIX
  const results = transactionList.map(item => {

      // A. Validasi Error dari AI
      if (item.isValid === false || item.status === "INVALID") {
         return { json: { isValid: false, message: item.message || "Format tidak dikenali." } };
      }

      // B. 🛠️ SMART DATE HANDLING (FITUR BARU)
      let finalDate = item.date;
      const today = new Date();

      // Skenario 1: Tanggal Kosong/Null -> Pake HARI INI
      if (!finalDate || finalDate === "" || finalDate === null) {
          const dd = String(today.getDate()).padStart(2, '0');
          const mm = String(today.getMonth() + 1).padStart(2, '0');
          const yyyy = today.getFullYear();
          finalDate = `${dd}-${mm}-${yyyy}`;
      } 
      // Skenario 2: Tanggal masih teks "23 Januari 2026" -> Kita Translate
      else if (!finalDate.match(/^\d{2}-\d{2}-\d{4}$/)) {
          // Coba cari pola angka dan teks bulan
          const parts = finalDate.split(/[\s-]+/); // Pisah spasi atau strip
          if (parts.length >= 3) {
              const day = parts[0].padStart(2, '0');
              const monthRaw = parts[1].toLowerCase();
              const year = parts[2];

              // Cek kamus bulan
              const monthNum = monthMap[monthRaw] || monthRaw; // Kalau gak ketemu, pake aslinya
              finalDate = `${day}-${monthNum}-${year}`;
          }
      }

      // C. Sanitasi Angka & Merchant
      let cleanTotal = item.total;
      if (typeof cleanTotal === 'string') {
          cleanTotal = parseInt(cleanTotal.replace(/[^0-9]/g, ''));
      }

      let cleanMerchant = item.merchant;
      if (!cleanMerchant || cleanMerchant === "") {
          cleanMerchant = "Tanpa Nama"; // Default value
      }

      // D. Bikin Periode (Grouping)
      const listBulan = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", 
                         "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
      let periode;
      try {
          const p = finalDate.split('-'); 
          const bIdx = parseInt(p[1]) - 1;
          periode = `${listBulan[bIdx]} ${p[2]}`;
      } catch (e) {
          periode = `${listBulan[today.getMonth()]} ${today.getFullYear()}`;
      }

      // E. Return Data Matang
      return {
        json: {
          ...item,
          date: finalDate,       // Tanggal yang sudah pasti terisi
          total: cleanTotal,     // Angka bersih
          merchant: cleanMerchant,
          periode: periode,
          isValid: true
        }
      };
  });

  return results;

} catch (error) {
  return [{
    json: {
      isValid: false,
      message: "Gagal memproses data. Coba format: 'Gaji 5jt hari ini'",
      debug_raw: aiResponse, 
      error: error.message
    }
  }];
}

// 1. GET DATA
const items = $input.all();
const now = new Date();

const userMessage = String(
  $('Switch').first()?.json?.message?.text ?? ''
).toLowerCase();

// 2. MONTH DETECTION
const monthMap = {
  januari: 0, jan: 0,
  februari: 1, feb: 1,
  maret: 2, mar: 2,
  april: 3, apr: 3,
  mei: 4, may: 4,
  juni: 5, jun: 5,
  juli: 6, jul: 6,
  agustus: 7, aug: 7,
  september: 8, sep: 8,
  oktober: 9, okt: 9, october: 9, oct: 9,
  november: 10, nov: 10,
  desember: 11, des: 11, december: 11, dec: 11
};

const monthMatch = userMessage.match(
  /\b(januari|jan|februari|feb|maret|mar|april|apr|mei|may|juni|jun|juli|jul|agustus|aug|september|sep|oktober|okt|october|oct|november|nov|desember|des|december|dec)\s*(20\d{2})?\b/
);

const targetMonth = monthMatch
  ? monthMap[monthMatch[1]]
  : now.getMonth();

const targetYear = monthMatch?.[2]
  ? Number(monthMatch[2])
  : now.getFullYear();

const targetPeriod = new Date(targetYear, targetMonth, 1)
  .toLocaleDateString('id-ID', {
    month: 'long',
    year: 'numeric'
  });

// 3. FINANCIAL COUNTERS
let expenseBulanIni = 0;
let incomeBulanIni = 0;

let rincianExpense = [];
let jumlahTransaksi = 0;

// 4. PROCESS ALL TRANSACTIONS
for (const item of items) {
  const data = item.json;

  // Safe amount parsing
  const rawAmount = data.Total;

  let harga = 0;

  if (typeof rawAmount === 'number' && Number.isFinite(rawAmount)) {
    harga = rawAmount;
  } else {
    const digits = String(rawAmount ?? '').replace(/[^\d]/g, '');
    harga = digits ? Number(digits) : 0;
  }

  // Parse date: DD-MM-YYYY or DD/MM/YYYY
  const dateValue = String(
    data.Date ?? data.date ?? ''
  ).trim();

  const dateMatch = dateValue.match(
    /^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/
  );

  if (!dateMatch) continue;

  const day = Number(dateMatch[1]);
  const transMonth = Number(dateMatch[2]) - 1;
  const transYear = Number(dateMatch[3]);

  // Validate actual calendar date
  const parsedDate = new Date(
    Date.UTC(transYear, transMonth, day)
  );

  const validDate =
    parsedDate.getUTCDate() === day &&
    parsedDate.getUTCMonth() === transMonth &&
    parsedDate.getUTCFullYear() === transYear;

  if (!validDate) continue;

  // Filter requested month and year
  if (
    transMonth !== targetMonth ||
    transYear !== targetYear
  ) continue;

  jumlahTransaksi++;

  const category = String(
    data.Category ?? ''
  ).trim().toLowerCase();

  // Separate income and expense
  if (category === 'pemasukan') {
    incomeBulanIni += harga;
  } else {
    expenseBulanIni += harga;

    const kategori = data.Category || 'Tanpa Kategori';
    const barang = data.Items || 'Item';
    const merchant = data.Merchant || 'Tidak diketahui';

    rincianExpense.push({
      amount: harga,
      text: `🔻 ${dateValue} | [${kategori}] ${merchant} (${barang}): Rp ${harga.toLocaleString('id-ID')}`
    });
  }
}

// 5. FORMAT OUTPUT
const expenseFmt = expenseBulanIni.toLocaleString('id-ID');
const incomeFmt = incomeBulanIni.toLocaleString('id-ID');

// Sort expenses by highest amount, show top 10
const topExpenses = rincianExpense
  .sort((a, b) => b.amount - a.amount)
  .slice(0, 10)
  .map(item => item.text);

const teksRincian = topExpenses.length
  ? topExpenses.join('\n')
  : 'Tidak ada transaksi pengeluaran pada periode ini.';

// 6. SEND VALIDATED DATA TO AI
return {
  json: {
    total_pengeluaran: `Rp ${expenseFmt}`,
    total_pemasukan: `Rp ${incomeFmt}`,

    pesan_untuk_ai: `SYSTEM DATA (VALIDATED):

PERIODE LAPORAN: ${targetPeriod}

RINGKASAN KEUANGAN:
- TOTAL PEMASUKAN: Rp ${incomeFmt}
- TOTAL PENGELUARAN: Rp ${expenseFmt}
- JUMLAH TRANSAKSI: ${jumlahTransaksi}

TOP 10 TRANSAKSI PENGELUARAN:
${teksRincian}

INSTRUKSI AI:
- Gunakan periode laporan di atas sebagai acuan.
- Jangan menganggap periode laporan selalu bulan berjalan.
- Jika jumlah transaksi = 0, informasikan bahwa tidak ada transaksi tercatat pada periode tersebut.
- Bandingkan pemasukan dan pengeluaran secara objektif.
- Jika pemasukan lebih besar, jelaskan surplus.
- Jika pengeluaran lebih besar, jelaskan defisit.
- Jangan mengarang angka atau transaksi.
- Jika user meminta rincian di luar Top 10, gunakan database transaksi sebagai sumber tambahan.`
  }
};

