// Mencari blok JSON pertama yang ditemukan
const jsonMatch = rawText.match(/\{[\s\S]*?\}/); 

if (jsonMatch) {
  try {
    return JSON.parse(jsonMatch[0]);
  } catch (e) {
    return { error: "Gagal parse JSON: " + e.message };
  }
}
return { error: "JSON tidak ditemukan" };
